"use client";

import { useMemo, useState } from "react";

const OMEGA = [1, 2, 3, 4, 5, 6];
export const GENS: { label: string; set: number[] }[] = [
  { label: "at most 3", set: [1, 2, 3] },
  { label: "even", set: [2, 4, 6] },
  { label: "a six", set: [6] },
  { label: "1 or 2", set: [1, 2] },
];

/** Atoms of the σ-algebra generated by the chosen sets: outcomes are grouped by which generators contain them. */
export function atomsOf(chosen: number[]) {
  const groups = new Map<string, number[]>();
  for (const w of OMEGA) {
    const key = chosen.map((g) => (GENS[g].set.includes(w) ? 1 : 0)).join("");
    groups.set(key, [...(groups.get(key) ?? []), w]);
  }
  return [...groups.values()];
}

const STYLES = [
  { fill: "var(--accent)", op: 0.75 }, { fill: "var(--code-function)", op: 0.75 }, { fill: "var(--text)", op: 0.55 },
  { fill: "var(--accent)", op: 0.3 }, { fill: "var(--code-function)", op: 0.3 }, { fill: "var(--text)", op: 0.2 },
];

export function SigmaAtomsViz() {
  const [on, setOn] = useState<boolean[]>([true, false, false, false]);
  const chosen = GENS.map((_, i) => i).filter((i) => on[i]);
  const atoms = useMemo(() => atomsOf(chosen), [on]); // eslint-disable-line react-hooks/exhaustive-deps
  const atomOf = (w: number) => atoms.findIndex((a) => a.includes(w));
  const W = 330, H = 92, S = 44, GAP = 8, X0 = (W - 6 * S - 5 * GAP) / 2;
  return (
    <figure className="viz">
      <div className="viz-controls" style={{ marginTop: 0, flexWrap: "wrap", gap: 6 }}>
        <span className="viz-label">generating events</span>
        {GENS.map((g, i) => (
          <button key={g.label} type="button" className="btn" aria-pressed={on[i]} style={{ fontWeight: on[i] ? 600 : 400, opacity: on[i] ? 1 : 0.6 }} onClick={() => setOn(on.map((v, j) => (j === i ? !v : v)))}>
            {on[i] ? "✓ " : ""}{g.label} {`{${g.set.join(", ")}}`}
          </button>
        ))}
      </div>
      <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", maxWidth: 440, display: "block", margin: "0 auto" }} role="img" aria-label="The six faces of a die grouped into atoms">
        {OMEGA.map((w, i) => {
          const a = atomOf(w), st = STYLES[a % STYLES.length], x = X0 + i * (S + GAP);
          return (
            <g key={w}>
              <rect x={x} y={8} width={S} height={S} rx={6} fill={st.fill} fillOpacity={st.op} stroke="var(--border)" />
              <text x={x + S / 2} y={8 + S / 2 + 6} textAnchor="middle" style={{ fontSize: 18, fill: "var(--text)" }}>{w}</text>
              <text x={x + S / 2} y={8 + S + 18} textAnchor="middle" className="viz-label">A{a + 1}</text>
            </g>
          );
        })}
      </svg>
      <div className="mono" style={{ fontSize: 12, margin: "6px 0" }} aria-live="polite">
        {chosen.length} generator{chosen.length === 1 ? "" : "s"}; atoms {atoms.map((a) => `{${a.join(",")}}`).join(" ")}; the σ-algebra has 2^{atoms.length} = {2 ** atoms.length} events
      </div>
      <figcaption className="viz-caption">
        Choose which events about a die roll you can observe. The σ-algebra they generate splits the faces into atoms,
        the smallest events you can tell apart, and every event in it is a union of atoms. Knowing only &quot;at most 3&quot; gives
        2 atoms and 4 events; adding &quot;even&quot; gives atoms {"{1, 3}, {2}, {4, 6}, {5}"} and 16 events; all four generators separate
        every face and give all 64 subsets.
      </figcaption>
    </figure>
  );
}
